int64_t returnBufValue(Exiv2::DataBuf& buf, int n = 4) {
  int64_t temp = 0;
  for (int i = n - 1; i >= 0; i--)
#ifdef _MSC_VER
    temp = temp + static_cast<int64_t>(buf.data()[i] * (pow(static_cast<float>(256), n - i - 1)));
#else
    temp = temp + buf.data()[i] * (pow((float)256, n - i - 1));
#endif

  return temp;
}
